package com.vault.controller;import com.vault.dto.Views;import com.vault.repository.ActivityLogRepository;import com.vault.service.AccountService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api")public class ActivityController{private final ActivityLogRepository logs;private final AccountService users;private final com.vault.service.KeyService keys;public ActivityController(ActivityLogRepository l,AccountService u,com.vault.service.KeyService k){logs=l;users=u;keys=k;}@GetMapping("/activity")public List<Views.ActivityView> activity(Authentication a){return logs.findTop100ByUserIdOrderByCreatedAtDesc(users.current(a.getName()).getId()).stream().map(Views.ActivityView::from).toList();}@GetMapping("/dashboard/stats")public Views.Stats stats(Authentication a){return keys.stats(a.getName());}}
